(26, 1, '2024-11-01 22:04:25', '2024-11-01 22:04:25', '<!-- wp:carbon-fields/service-main-screen {\"data\":{\"dolphincargo_service_main_screen_title\":\"МОРСЬКА ДОСТАВКА ВАНТАЖІВ З КИТАЮ В УКРАЇНУ\",\"dolphincargo_service_main_screen_who_are_we\":\"Надійно, вчасно та безпечно\",\"dolphincargo_service_main-screen_image\":\"http://dolphincargo.loc/wp-content/uploads/2024/11/service-1-main-bg.png\"}} /-->\n\n<!-- wp:carbon-fields/our-achievement {\"data\":{\"dolphincargo_achievement_image\":159,\"dolphincargo_achievement_main\":\"3536 \",\"dolphincargo_achievement_description\":\"вантажів доставили морем  за 2024 рік\",\"dolphincargo_achievement_list\":[{\"_id\":\"cf-AD2NYI1NbyOWatBXMj_u0\",\"_type\":\"_\",\"name\":\"Повний спектр послуг \",\"description\":\"\\u003cp\\u003eМи пропонуємо морську доставку з Китаю, митне оформлення вантажів та всіх необхідних документів.\\u003c/p\\u003e\"},{\"_id\":\"cf-xbf5iOSRToSR0DhbrGnKi\",\"_type\":\"_\",\"name\":\"100% професіоналізм \",\"description\":\"\\u003cp\\u003eМи працюємо без посередників, тому відповідаємо за кожен етап. Маємо власні склади у ключових транспортних вузлах: Китай, ЄС, Україна.\\u003c/p\\u003e\"}]}} /-->\n\n<!-- wp:carbon-fields/warrantyservices {\"data\":{\"dolphincargo_warranty_title\":\"НАШІ послуги\",\"dolphincargo_warranty_list\":[{\"_id\":\"cf-RYgYhqruFPhGqWtvyH4G4\",\"_type\":\"_\",\"name\":\"Морська доставка вантажів з Китаю\",\"image\":164},{\"_id\":\"cf-WQVbGENz8TvhKPwnekRQL\",\"_type\":\"_\",\"name\":\"Доставка збірних вантажів з Китаю морем\",\"image\":163},{\"_id\":\"cf-u_1vKxpaoccSUKM3GXBav\",\"_type\":\"_\",\"name\":\"Склади в Китаї, Європі, Україні для зберігання товарів\",\"image\":162},{\"_id\":\"cf-yxbvHwtOuTHHogXaOzJsP\",\"_type\":\"_\",\"name\":\"Повний супровід та оформлення документів\",\"image\":161}],\"dolphincargo_warranty_logic\":\"yes\"}} /-->\n\n<!-- wp:carbon-fields/calculate-shipping {\"data\":{\"dolphincargo_calculate_shipping_title\":\"БАЖАЄТЕ РОЗРАХУВАТИ ВАРТІСТЬ ДОСТАВКИ? \",\"dolphincargo_calculate_shipping_text\":\"\\u003cp\\u003eНаші менеджери підберуть найкращі індивідуальні рішення для вас та прорахують вартість послуг\\u003c/p\\u003e\",\"dolphincargo_calculate_shipping_image\":167}} /-->\n\n<!-- wp:carbon-fields/delivery-steps {\"data\":{\"dolphincargo_delivery_steps_title\":\"ЯК ПРАЦЮЄ НАША ДОСТАВКА?\",\"dolphincargo_delivery_steps_list\":[{\"_id\":\"cf-fWSbHjMvL19GwDX4H0lf1\",\"_type\":\"_\",\"text\":\"Ви залишаєте заявку на доставку вантажу та обираєте умови перевезення разом з персональним менеджером.\"},{\"_id\":\"cf-16nv0AV1_AkkNrLdY6g3F\",\"_type\":\"_\",\"text\":\"Ваш постачальник відправляє вантаж на наш особистий склад, після його отримання ми готуємо товар до відправлення.\"},{\"_id\":\"cf-yPtJgSomfMqbDFVDmUUgv\",\"_type\":\"_\",\"text\":\"Оформлюємо всі необхідні митні документи для експорту з Китаю.\"},{\"_id\":\"cf-It1NQdyVeYfxhgTWGdqJL\",\"_type\":\"_\",\"text\":\"Наші фахівці завантажують ваш вантаж в збірний контейнер, після чого він відправляється на контейнерне судно.\"},{\"_id\":\"cf-y47uehIqxZrpDZ3Vw2CWu\",\"_type\":\"_\",\"text\":\"Під час перевезення ми тримаємо звʼязок, відстежуємо вантаж та контролюємо графік доставки.\"},{\"_id\":\"cf-5rBvcsZZsiL0CDdakTrHz\",\"_type\":\"_\",\"text\":\"Після прибуття борту до місця призначення, наші спеціалісти проводять митне оформлення вантажу.\"},{\"_id\":\"cf-p6FfIIGsxfCGOZ6klHkaO\",\"_type\":\"_\",\"text\":\"Вантаж доставляється до нашого складу в Одесі, а потім безпосередньо  до необхідного Вам місця призначення.\"}],\"dolphincargo_delivery_steps_road_pic\":242,\"dolphincargo_delivery_steps_transport_pic\":239,\"dolphincargo_delivery_steps_image_position\":\"road\",\"dolphincargo_delivery_steps_road_pic_more\":241}} /-->\n\n<!-- wp:carbon-fields/advantages-delivery {\"data\":{\"dolphincargo_advantages_delivery_title\":\"ПЕРЕВАГИ ДОСТАВКИ МОРЕМ\",\"dolphincargo_advantages_delivery_list\":[{\"_id\":\"cf-WmNRLqGLmndUT6JCivdyM\",\"_type\":\"_\",\"icon\":\"http://dolphincargo.loc/wp-content/uploads/2024/11/frame-427322787_optimized.png\",\"name\":\"Конкурентні ціни.\",\"text\":\"\\u003cp\\u003eЦіна доставки вантажу морем з Китаю значно нижча за інші види транспорту.\\u003c/p\\u003e\"},{\"_id\":\"cf-pqAqSy_712cFsHIhox1oS\",\"_type\":\"_\",\"icon\":\"http://dolphincargo.loc/wp-content/uploads/2024/11/frame-427322788_optimized.png\",\"name\":\"Надійність.\",\"text\":\"\\u003cp\\u003eМорська доставка – один із найбезпечніших способів транспортування вантажів.\\u003c/p\\u003e\"},{\"_id\":\"cf-TSwGG2bYKaFwB0zBGyU2N\",\"_type\":\"_\",\"icon\":\"http://dolphincargo.loc/wp-content/uploads/2024/11/frame-427322789_optimized.png\",\"name\":\"Потенціал.\",\"text\":\"\\u003cp\\u003eВи можете доставляти великі обсяги вантажу за один раз.\\u003c/p\\u003e\"}]}} /-->\n\n<!-- wp:carbon-fields/cargo-services {\"data\":{\"dolphincargo_cargo_services_title\":\"DOLPHIN CARGO SERVICE\",\"dolphincargo_cargo_services_text\":\"\\u003cp\\u003eМи забезпечуємо високий рівень сервісу доставки для вашого повного комфорту та спокою\\u003c/p\\u003e\",\"dolphincargo_cargo_services_list\":[{\"_id\":\"cf-DZ14alVevOsKLuU_N_gw1\",\"_type\":\"_\",\"name\":\"Безпечно\",\"list\":[{\"_id\":\"cf-uDye3cesiPgoyhhpBt9Rj\",\"_type\":\"_\",\"text\":\"Несемо відповідальність за коректне оформлення документації \"},{\"_id\":\"cf-FvVsupAmDBB7JLridOKId\",\"_type\":\"_\",\"text\":\"Надаємо повне страхування вантажу\"},{\"_id\":\"cf-FSFqX1s2QNomFq8ttQHnl\",\"_type\":\"_\",\"text\":\"Перевіряємо товар, за необхідності перепаковуємо та доставляємо\"},{\"_id\":\"cf-k3mhcwVfi5alcmZC2MJvA\",\"_type\":\"_\",\"text\":\"Контролюємо особисто кожен етап доставки, адже працюємо без посередників \"}]},{\"_id\":\"cf-QdHZ7kOed2fmmfD7PJPLP\",\"_type\":\"_\",\"name\":\"Зручно\",\"list\":[{\"_id\":\"cf-_JpoAEiDChAyPswvjryvu\",\"_type\":\"_\",\"text\":\"Ви отримуєте підтримку кваліфікованого менеджера на всіх етапах доставки\"},{\"_id\":\"cf-TdepWpVy0AqjUqTvkEleQ\",\"_type\":\"_\",\"text\":\"Відслідковуйте статус замовлення в особистому кабінеті Dolphin Cargo Service\"},{\"_id\":\"cf-GvM3Rc_L3Hmj56REr595b\",\"_type\":\"_\",\"text\":\"Перевіряємо товар, за необхідності перепаковуємо та доставляємо\"},{\"_id\":\"cf-sDdDbgWpzbDhPxW5Hnk0P\",\"_type\":\"_\",\"text\":\"Контролюємо особисто кожен етап доставки, адже працюємо без посередників \"}]},{\"_id\":\"cf-snB8Vn02cGU2tuI4VP6Cx\",\"_type\":\"_\",\"name\":\"Надійно\",\"list\":[{\"_id\":\"cf-MKvYZRXbgTkxrldlhyIra\",\"_type\":\"_\",\"text\":\"Маємо власні склади в Китаї, ЄС та Україні, що гарантує належні умови зберігання вантажів, економію вашого часу та коштів. \"},{\"_id\":\"cf-zVR1xGkfINK8yK17uD_sy\",\"_type\":\"_\",\"text\":\"Надаємо ключові складські послуги.\"},{\"_id\":\"cf-9y5DK4y4upnH_rBQkd6S9\",\"_type\":\"_\",\"text\":\"19 років налагодженої роботи з доставкою вантажів з Китаю морем. \"}]}]}} /-->\n\n<!-- wp:carbon-fields/call-to-action {\"data\":{\"dolphincargo_call_to_action_title\":\"БАЖАЄТЕ ОТРИМАТИ КОНСУЛЬТАЦІЮ?\",\"dolphincargo_call_to_action_text\":\"\\u003cp\\u003eЗалишайте заявку і наші менеджери нададуть відповіді на всі ваші питання.\\u003c/p\\u003e\",\"dolphincargo_call_to_action_image\":183}} /-->\n\n<!-- wp:carbon-fields/reviews-block {\"data\":{\"dolphincargo_block_reviews_title\":\"ВІДГУКИ НАШИХ КЛІЄНТІВ\"}} /-->\n\n<!-- wp:carbon-fields/faq-block {\"data\":{\"dolphincargo_block_faq_title\":\"Питання та вiдповiдi\",\"dolphincargo_block_faq_list\":[{\"_id\":\"cf-AUqx_ate1mxBFpXzj3NUQ\",\"_type\":\"_\",\"question\":\"Чи можете ви допомогти з підбором постачальників у Китаї?\",\"answer\":\"\\u003cp\\u003eDolphin Cargo — ми лідери серед українських логістичних компаній, що спеціалізуються на доставці вантажів з Китаю та Європи. З 2005 року ведемо бездоганну роботу, регулярно масштабуючи власні можливості та покращуючи сервіс для наших клієнтів. Dolphin Cargo — ми лідери серед українських логістичних компаній, що спеціалізуються на доставці вантажів з Китаю та Європи. З 2005 року ведемо бездоганну роботу, регулярно масштабуючи власні можливості та покращуючи сервіс для наших клієнтів.\\u003c/p\\u003e\"},{\"_id\":\"cf-Xf3XOzN53B4hxXNeV8qfr\",\"_type\":\"_\",\"question\":\"Чи можете ви допомогти з підбором постачальників у Китаї?\",\"answer\":\"\\u003cp\\u003eDolphin Cargo — ми лідери серед українських логістичних компаній, що спеціалізуються на доставці вантажів з Китаю та Європи. З 2005 року ведемо бездоганну роботу, регулярно масштабуючи власні можливості та покращуючи сервіс для наших клієнтів. Dolphin Cargo — ми лідери серед українських логістичних компаній, що спеціалізуються на доставці вантажів з Китаю та Європи. З 2005 року ведемо бездоганну роботу, регулярно масштабуючи власні можливості та покращуючи сервіс для наших клієнтів.\\u003c/p\\u003e\"}]}} /-->\n\n<!-- wp:carbon-fields/blog-block {\"data\":{\"dolphincargo_block_blog_title\":\"КОРИСНИЙ КОНТЕНТ\",\"dolphincargo_block_blog_link\":[{\"id\":18,\"type\":\"post\",\"subtype\":\"page\"}]}} /-->\n\n<!-- wp:carbon-fields/seo-block {\"data\":{\"dolphincargo_home_page_seo_title\":\"БЛОК ДЛЯ SEO-ТЕКСТУ \",\"dolphincargo_home_page_seo_subtitle\":\"Заголовок\",\"dolphincargo_home_page_seo_text\":\"\\u003ch3\\u003eЗаголовок\\u003c/h3\\u003e\\n\\u003cp\\u003e\\u003cbr /\\u003eDolphin Cargo — ми лідери серед українських логістичних компаній, що спеціалізуються на доставці вантажів з Китаю та Європи. З 2005 року ведемо бездоганну роботу, регулярно масштабуючи власні можливості та покращуючи сервіс для наших клієнтів. Dolphin Cargo — ми лідери серед українських логістичних компаній, що спеціалізуються на доставці вантажів з Китаю та Європи. З 2005 року ведемо бездоганну роботу, регулярно масштабуючи власні можливості та покращуючи сервіс для наших клієнтів.\\u003c/p\\u003e\\n\\u003ch3\\u003eЗаголовок 2\\u003c/h3\\u003e\\n\\u003cp\\u003e\\u003cbr /\\u003eDolphin Cargo — ми лідери серед українських логістичних компаній, що спеціалізуються на доставці вантажів з Китаю та Європи. З 2005 року ведемо бездоганну роботу, регулярно масштабуючи власні можливості та покращуючи сервіс для наших клієнтів. Dolphin Cargo — ми лідери серед українських логістичних компаній, що спеціалізуються на доставці вантажів з Китаю та Європи. З 2005 року ведемо бездоганну роботу, регулярно масштабуючи власні можливості та покращуючи сервіс для наших клієнтів.\\u003c/p\\u003e\"}} /-->', 'Доставка вантажів із Китаю морем', 'Доставка вантажів з Китаю морем є економним  рішенням перевезення великих обсягів товарів. Ми забезпечимо оптимальні маршрути та вигідні тарифи завдяки налагодженим зв’язкам та досвіду.', 'publish', 'closed', 'closed', '', 'dostavka-vantazhiv-iz-kytayu-morem', '', '', '2024-12-29 14:15:15', '2024-12-29 14:15:15', '', 0, 'http://dolphincargo.loc/?post_type=services&#038;p=26', 0, 'services', '', 0),
(27, 1, '2024-11-01 22:04:48', '2024-11-01 22:04:48', '<!-- wp:carbon-fields/service-main-screen {\"data\":{\"dolphincargo_service_main_screen_title\":\"АВІА ДОСТАВКА ВАНТАЖІВ INSERT INTO `yudoca_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(28, 1, '2024-11-01 22:04:59', '2024-11-01 22:04:59', '<!-- wp:carbon-fields/service-main-screen {\"data\":{\"dolphincargo_service_main_screen_title\":\"ЗАЛІЗНИЧНА ДОСТАВКА ВАНТАЖІВ З КИТАЮ В УКРАЇНУ\",\"dolphincargo_service_main_screen_who_are_we\":\"Ідеальне співвідношення вартості та термінів транспортування\",\"dolphincargo_service_main-screen_image\":\"http://dolphincargo.loc/wp-content/uploads/2024/11/mask-group_optimized-1.png\"}} /-->\n\n<!-- wp:carbon-fields/our-achievement {\"data\":{\"dolphincargo_achievement_image\":278,\"dolphincargo_achievement_main\":\"19 років \",\"dolphincargo_achievement_description\":\"клієнти нам довіряють свої вантажі\",\"dolphincargo_achievement_list\":[{\"_id\":\"cf-EudYH0CE9OK2MpKN4PYu7\",\"_type\":\"_\",\"name\":\"Рекомендоване рішення для відправлень з великою вантажопідйомністю\",\"description\":\"\\u003cp\\u003eПотяги здатні транспортувати значні обсяги товарів в оптимальні терміни, що робить цей спосіб ідеальним для транспортування вантажів.\\u003c/p\\u003e\"},{\"_id\":\"cf-muVpqvHPpZGbF7dMDjqP6\",\"_type\":\"_\",\"name\":\"Залізнична доставка “під ключ”\",\"description\":\"\\u003cp\\u003eВід першого звернення на сайті до адресної доставки: організовуємо всю логістику, страхування, митно-брокерські послуги та контроль вантажу на кожному кроці.\\u003c/p\\u003e\"}]}} /-->\n\n<!-- wp:carbon-fields/warrantyservices {\"data\":{\"dolphincargo_warranty_title\":\"НАШІ ГАРАНТІЇ\",\"dolphincargo_warranty_list\":[{\"_id\":\"cf-Brg8c8VHIbKDlD41l1ueU\",\"_type\":\"_\",\"name\":\"Гарантія безпеки вантажів\",\"image\":267},{\"_id\":\"cf-1PjyjGFhshEqyHKBIORA5\",\"_type\":\"_\",\"name\":\"Доставка у зазначені терміни\",\"image\":270},{\"_id\":\"cf-Ue6KmdiKkPxFBW2uX9xi1\",\"_type\":\"_\",\"name\":\"Страхування вантажу\",\"image\":269},{\"_id\":\"cf-5yZDYiBl482QR92IVK01F\",\"_type\":\"_\",\"name\":\"Повна конфіденційність\",\"image\":268}],\"dolphincargo_warranty_logic\":\"no\"}} /-->\n\n<!-- wp:carbon-fields/calculate-shipping {\"data\":{\"dolphincargo_calculate_shipping_title\":\"БАЖАЄТЕ РОЗРАХУВАТИ ВАРТІСТЬ ДОСТАВКИ? \",\"dolphincargo_calculate_shipping_text\":\"\\u003cp\\u003eНаші менеджери підберуть найкращі індивідуальні рішення для вас та прорахують вартість послуг\\u003c/p\\u003e\",\"dolphincargo_calculate_shipping_image\":167}} /-->\n\n<!-- wp:carbon-fields/delivery-steps {\"data\":{\"dolphincargo_delivery_steps_title\":\"ЯК ПРАЦЮЄ НАША ДОСТАВКА?\",\"dolphincargo_delivery_steps_list\":[{\"_id\":\"cf-b_iORtUyEm0HQLyKctLEl\",\"_type\":\"_\",\"text\":\"Ви залишаєте заявку на доставку вантажу та обираєте умови перевезення разом з персональним менеджером.\"},{\"_id\":\"cf-05MfypAt99pdL6qcp0dpR\",\"_type\":\"_\",\"text\":\"Ваш постачальник відправляє вантаж на наш особистий склад. Після отримання товару наші фахівці перевіряють його пакування та готують до відправки потягом.\"},{\"_id\":\"cf-lHRYv2PN4S8CQ6u4ukjdB\",\"_type\":\"_\",\"text\":\"Ми оформлюємо всі необхідні митні документи для експорту вантажу з Китаю.\"},{\"_id\":\"cf-GTvlSaNX8rjInsUFsy5iW\",\"_type\":\"_\",\"text\":\"Необхідну вам партію завантажуємо у збірний контейнер на залізничному терміналі та відправляється потягом за визначеним маршрутом до місця призначення.\"},{\"_id\":\"cf-qrQUw8qeM6Au1ZGTGZs3E\",\"_type\":\"_\",\"text\":\"Під час перевезення ми тримаємо звʼязок із залізничними операторами, відстежуємо вантаж та контролюємо графік доставки.\"},{\"_id\":\"cf-n2Zuo8eBiYqr9oFKgOxcX\",\"_type\":\"_\",\"text\":\"Після прибуття борту до місця призначення, наші спеціалісти проводять митне оформлення вантажу.\"},{\"_id\":\"cf-slIzjw8h1t6irxqwkz661\",\"_type\":\"_\",\"text\":\"Вантаж доставляється до нашого складу в Одесі, а потім безпосередньо  до необхідного Вам місця призначення.\"}],\"dolphincargo_delivery_steps_transport_pic\":283,\"dolphincargo_delivery_steps_road_pic\":446,\"dolphincargo_delivery_steps_image_position\":\"transport\",\"dolphincargo_delivery_steps_road_pic_more\":\"\"}} /-->\n\n<!-- wp:carbon-fields/advantages-delivery {\"data\":{\"dolphincargo_advantages_delivery_title\":\"ПЕРЕВАГИ ЗАЛІЗНИЧНОЇ ДОСТАВКИ\",\"dolphincargo_advantages_delivery_list\":[{\"_id\":\"cf-zJSIK9xQYhvhzJcPA0wjl\",\"_type\":\"_\",\"icon\":\"http://dolphincargo.loc/wp-content/uploads/2024/11/frame-427322787_optimized.png\",\"name\":\"Конкурентні ціни.\",\"text\":\"\\u003cp\\u003eЗалізнична доставка є вигідним рішенням, яке забезпечує оптимальний баланс між вартістю та швидкістю транспортування.\\u003c/p\\u003e\"},{\"_id\":\"cf-CiWl3XPrvb9FQWeXad64f\",\"_type\":\"_\",\"icon\":\"http://dolphincargo.loc/wp-content/uploads/2024/11/frame-4273227883_optimized.png\",\"name\":\"Надійність.\",\"text\":\"\\u003cp\\u003eЗалізничний транспорт має високу точність дотримання графіків та мінімальний ризик пошкодження вантажу завдяки стабільності перевезень.\\u003c/p\\u003e\"}]}} /-->\n\n<!-- wp:carbon-fields/cargo-services {\"data\":{\"dolphincargo_cargo_services_title\":\"DOLPHIN CARGO SERVICE\",\"dolphincargo_cargo_services_text\":\"\\u003cp\\u003eМи забезпечуємо високий рівень сервісу доставки для вашого повного комфорту та спокою\\u003c/p\\u003e\",\"dolphincargo_cargo_services_list\":[{\"_id\":\"cf-wyGcQeETkMRz1p3JXz0TG\",\"_type\":\"_\",\"name\":\"Безпечно\",\"list\":[{\"_id\":\"cf-RXEKRJH06Nq93g8pgMTNF\",\"_type\":\"_\",\"text\":\"Несемо відповідальність за коректне оформлення документації \"},{\"_id\":\"cf-hH5hYFbuJNi2umue2YKD3\",\"_type\":\"_\",\"text\":\"Надаємо повне страхування вантажу\"},{\"_id\":\"cf-m2JiefN3MKNj2lbiUn8sC\",\"_type\":\"_\",\"text\":\"Перевіряємо товар, за необхідності перепаковуємо та доставляємо\"},{\"_id\":\"cf-fFlxPGeksJjLXx1FGPYRA\",\"_type\":\"_\",\"text\":\"Контролюємо особисто кожен етап доставки, адже працюємо без посередників \"}]},{\"_id\":\"cf-FSvlBv2zEiKdgCmMTjYeH\",\"_type\":\"_\",\"name\":\"Зручно\",\"list\":[{\"_id\":\"cf-UHsc7zXNfAGHsWNb270mM\",\"_type\":\"_\",\"text\":\"Ви отримуєте підтримку кваліфікованого менеджера на всіх етапах доставки\"},{\"_id\":\"cf-oWgGu9WPWzxJvoxUM_Dgp\",\"_type\":\"_\",\"text\":\"Відслідковуйте статус замовлення в особистому кабінеті Dolphin Cargo Service\"},{\"_id\":\"cf-VRnPeLhgghLeBdid_4ajS\",\"_type\":\"_\",\"text\":\"Перевіряємо товар, за необхідності перепаковуємо та доставляємо\"},{\"_id\":\"cf-z736SAd7KSA9FAmawDTnQ\",\"_type\":\"_\",\"text\":\"Контролюємо особисто кожен етап доставки, адже працюємо без посередників \"}]},{\"_id\":\"cf-0j9hiYwNN0KF3cvZs9MWN\",\"_type\":\"_\",\"name\":\"Надійно\",\"list\":[{\"_id\":\"cf-34jEgxLCYdb60Qg_E6bpk\",\"_type\":\"_\",\"text\":\"Маємо власні склади в Китаї, ЄС та Україні, що гарантує належні умови зберігання вантажів, економію вашого часу та коштів. \"},{\"_id\":\"cf-lHU5YCileLxMUWhXlmrPQ\",\"_type\":\"_\",\"text\":\"Надаємо ключові складські послуги.\"},{\"_id\":\"cf-LlikFG5UbKIEbQO6NdpHk\",\"_type\":\"_\",\"text\":\"19 років налагодженої роботи з доставкою вантажів з Китаю морем. \"}]}]}} /-->\n\n<!-- wp:carbon-fields/call-to-action {\"data\":{\"dolphincargo_call_to_action_title\":\"БАЖАЄТЕ ОТРИМАТИ КОНСУЛЬТАЦІЮ?\",\"dolphincargo_call_to_action_text\":\"\\u003cp\\u003eЗалишайте заявку і наші менеджери нададуть відповіді на всі ваші питання.\\u003c/p\\u003e\",\"dolphincargo_call_to_action_image\":288}} /-->\n\n<!-- wp:carbon-fields/reviews-block {\"data\":{\"dolphincargo_block_reviews_title\":\"ВІДГУКИ НАШИХ КЛІЄНТІВ\"}} /-->\n\n<!-- wp:carbon-fields/faq-block {\"data\":{\"dolphincargo_block_faq_title\":\"Питання та вiдповiдi\",\"dolphincargo_block_faq_list\":[{\"_id\":\"cf-tX91uQKwhkn31xcWCAZaJ\",\"_type\":\"_\",\"question\":\"Чи можете ви допомогти з підбором постачальників у Китаї?\",\"answer\":\"\\u003cp\\u003eDolphin Cargo — ми лідери серед українських логістичних компаній, що спеціалізуються на доставці вантажів з Китаю та Європи. З 2005 року ведемо бездоганну роботу, регулярно масштабуючи власні можливості та покращуючи сервіс для наших клієнтів. Dolphin Cargo — ми лідери серед українських логістичних компаній, що спеціалізуються на доставці вантажів з Китаю та Європи. З 2005 року ведемо бездоганну роботу, регулярно масштабуючи власні можливості та покращуючи сервіс для наших клієнтів.\\u003c/p\\u003e\"},{\"_id\":\"cf-aGevfl86dYKsALYlBpX0e\",\"_type\":\"_\",\"question\":\"Чи можете ви допомогти з підбором постачальників у Китаї?\",\"answer\":\"\\u003cp\\u003eDolphin Cargo — ми лідери серед українських логістичних компаній, що спеціалізуються на доставці вантажів з Китаю та Європи. З 2005 року ведемо бездоганну роботу, регулярно масштабуючи власні можливості та покращуючи сервіс для наших клієнтів. Dolphin Cargo — ми лідери серед українських логістичних компаній, що спеціалізуються на доставці вантажів з Китаю та Європи. З 2005 року ведемо бездоганну роботу, регулярно масштабуючи власні можливості та покращуючи сервіс для наших клієнтів.\\u003c/p\\u003e\"}]}} /-->\n\n<!-- wp:carbon-fields/blog-block {\"data\":{\"dolphincargo_block_blog_title\":\"КОРИСНИЙ КОНТЕНТ\",\"dolphincargo_block_blog_link\":[{\"id\":18,\"type\":\"post\",\"subtype\":\"page\"}]}} /-->\n\n<!-- wp:carbon-fields/seo-block {\"data\":{\"dolphincargo_home_page_seo_title\":\"БЛОК ДЛЯ SEO-ТЕКСТУ \",\"dolphincargo_home_page_seo_subtitle\":\"Заголовок\",\"dolphincargo_home_page_seo_text\":\"\\u003ch3\\u003eЗаголовок\\u003c/h3\\u003e\\u003cp\\u003e\\u003cbr /\\u003eDolphin Cargo — ми лідери серед українських логістичних компаній, що спеціалізуються на доставці вантажів з Китаю та Європи. З 2005 року ведемо бездоганну роботу, регулярно масштабуючи власні можливості та покращуючи сервіс для наших клієнтів. Dolphin Cargo — ми лідери серед українських логістичних компаній, що спеціалізуються на доставці вантажів з Китаю та Європи. З 2005 року ведемо бездоганну роботу, регулярно масштабуючи власні можливості та покращуючи сервіс для наших клієнтів.\\u003c/p\\u003e\\u003cp\\u003e \\u003c/p\\u003e\\u003cp\\u003eDolphin Cargo — ми лідери серед українських логістичних компаній, що спеціалізуються на доставці вантажів з Китаю та Європи. З 2005 року ведемо бездоганну роботу, регулярно масштабуючи власні можливості та покращуючи сервіс для наших клієнтів. Dolphin Cargo — ми лідери серед українських логістичних компаній, що спеціалізуються на доставці вантажів з Китаю та Європи. З 2005 року ведемо бездоганну роботу, регулярно масштабуючи власні можливості та покращуючи сервіс для наших клієнтів.\\u003c/p\\u003e\"}} /-->', 'Доставка вантажів залізничним транспортом', 'Залізнична доставка з Китаю та Європи – баланс між швидкістю та вартістю. Ми гарантуємо безпеку ваших вантажів та контроль на кожному етапі транспортування. ', 'publish', 'closed', 'closed', '', 'dostavka-vantazhiv-zaliznychnym-transportom', '', '', '2025-01-11 08:24:26', '2025-01-11 08:24:26', '', 0, 'http://dolphincargo.loc/?post_type=services&#038;p=28', 0, 'services', '', 0),
(29, 1, '2024-11-01 22:05:16', '2024-11-01 22:05:16', '', 'Митне оформлення вантажів', 'Ми допоможемо підготувати всю необхідну документацію, заповнити декларації та уникнути можливих проблем із митними органами. Наші експерти гарантують мінімальні терміни проходження митниці.', 'publish', 'closed', 'closed', '', 'mytne-oformlennya-vantazhiv', '', '', '2024-12-29 14:17:18', '2024-12-29 14:17:18', '', 0, 'http://dolphincargo.loc/?post_type=services&#038;p=29', 0, 'services', '', 0),
(30, 1, '2024-11-01 22:05:34', '2024-11-01 22:05:34', '', 'Пошук та викуп товару в Китаї', 'Ми співпрацюємо з великою кількістю надійних виробників, що дозволяє забезпечити пошук необхідних товарів. Завдяки нашому досвіду ви зможете уникнути ризиків, пов’язаних із замовленням продукції з-за кордону.', 'publish', 'closed', 'closed', '', 'poshuk-ta-vykup-tovaru-v-kytayi', '', '', '2024-12-29 14:18:02', '2024-12-29 14:18:02', '', 0, 'http://dolphincargo.loc/?post_type=services&#038;p=30', 0, 'services', '', 0),
(31, 1, '2024-11-01 22:05:56', '2024-11-01 22:05:56', '', 'Доставка вантажів з Китаю під ключ', 'Доставка вантажу з контролем професіоналів на кожному з етапів: від пошуку товарів до отримання вами необхідного вантажу. Ми беремо на себе всю роботу, щоб ваш вантаж прибув точно в термін і без зайвого клопоту.', 'publish', 'closed', 'closed', '', 'dostavka-vantazhiv-z-kytayu-pid-klyuch', '', '', '2024-12-29 14:17:37', '2024-12-29 14:17:37', '', 0, 'http://dolphincargo.loc/?post_type=services&#038;p=31', 0, 'services', '', 0),
