(194, 1, '2024-12-28 12:20:17', '2024-12-28 12:20:17', '<!-- wp:carbon-fields/service-main-screen {\"data\":{\"dolphincargo_service_main_screen_title\":\"МОРСКАЯ ДОСТАВКА ГРУЗОВ ИЗ КИТАЯ В УКРАИНУ\",\"dolphincargo_service_main_screen_who_are_we\":\"Надежно, вовремя и безопасно\",\"dolphincargo_service_main-screen_image\":\"http://dolphincargo.loc/wp-content/uploads/2024/11/service-1-main-bg.png\"}} /-->\n\n<!-- wp:carbon-fields/our-achievement {\"data\":{\"dolphincargo_achievement_image\":294,\"dolphincargo_achievement_main\":\"3536\",\"dolphincargo_achievement_description\":\"Грузов доставили морем за 2024 год\",\"dolphincargo_achievement_list\":[{\"_id\":\"cf-r676W3b5h9jLeOV1PHhvO\",\"_type\":\"_\",\"name\":\"Полный спектр услуг\",\"description\":\"\\u003cp\\u003e\\u003cspan style=\\u0022font-weight: 400;\\u0022\\u003eМы предлагаем морскую доставку из Китая, таможенное оформление грузов и всех необходимых документов.\\u003c/span\\u003e\\u003c/p\\u003e\"},{\"_id\":\"cf-8lCNFh1virk0CXKz_WEyw\",\"_type\":\"_\",\"name\":\"100% профессионализм\",\"description\":\"\\u003cp\\u003e\\u003cspan style=\\u0022font-weight: 400;\\u0022\\u003eМы работаем без посредников, поэтому отвечаем за каждый этап доставки. У нас есть собственные склады в ключевых транспортных узлах: Китай, ЕС, Украина.\\u003c/span\\u003e\\u003c/p\\u003e\"}]}} /-->\n\n<!-- wp:carbon-fields/warrantyservices {\"data\":{\"dolphincargo_warranty_title\":\"НАШИ УСЛУГИ\",\"dolphincargo_warranty_list\":[{\"_id\":\"cf-c2aZfekjOGpd9zSrzYq3d\",\"_type\":\"_\",\"name\":\"Морская доставка грузов из Китая\",\"image\":299},{\"_id\":\"cf-rP7lZIxY7nto92VrbHkhd\",\"_type\":\"_\",\"name\":\"Доставка сборных грузов морем\",\"image\":297},{\"_id\":\"cf-T9hbqIjPKwDWuB9uE6SjQ\",\"_type\":\"_\",\"name\":\"Склады в Китае, Европе и Украине для хранения товаров\",\"image\":301},{\"_id\":\"cf-4lbhzMOC_WeTcMLMscE0q\",\"_type\":\"_\",\"name\":\"Полное сопровождение и оформление документов\",\"image\":303}],\"dolphincargo_warranty_logic\":\"yes\"}} /-->\n\n<!-- wp:carbon-fields/calculate-shipping {\"data\":{\"dolphincargo_calculate_shipping_title\":\"ХОТИТЕ РАССЧИТАТЬ СТОИМОСТЬ ДОСТАВКИ?\",\"dolphincargo_calculate_shipping_text\":\"\\u003cp\\u003e\\u003cspan style=\\u0022font-weight: 400;\\u0022\\u003eНаши менеджеры подберут лучшие индивидуальные решения для вас и рассчитают стоимость услуг.\\u003c/span\\u003e\\u003c/p\\u003e\",\"dolphincargo_calculate_shipping_image\":306}} /-->\n\n<!-- wp:carbon-fields/delivery-steps {\"data\":{\"dolphincargo_delivery_steps_title\":\"КАК РАБОТАЕТ НАША ДОСТАВКА?\",\"dolphincargo_delivery_steps_list\":[{\"_id\":\"cf-hLTxObsyPZxJxeu_x2SyJ\",\"_type\":\"_\",\"text\":\"Вы оставляете заявку на доставку груза и выбираете условия транспортировки с персональным менеджером.\"},{\"_id\":\"cf-Io5wpBG9hj9hIWsRcDx_c\",\"_type\":\"_\",\"text\":\"Ваш поставщик отправляет груз на наш склад. После его получения мы готовим товар к отправке.\"},{\"_id\":\"cf-ogXy7gvu7_owgwSiws2Ey\",\"_type\":\"_\",\"text\":\"Оформляем все необходимые таможенные документы для экспорта из Китая.\"},{\"_id\":\"cf-tzg0Q5FvmrXDK7tdEsaUd\",\"_type\":\"_\",\"text\":\"Наши специалисты загружают ваш груз в сборный контейнер, который отправляется на контейнерное судно.\"},{\"_id\":\"cf-W6NOOeM4hv3fth2HZaegs\",\"_type\":\"_\",\"text\":\"Во время перевозки мы остаёмся на связи, отслеживаем груз и контролируем график доставки.\"},{\"_id\":\"cf-tsNGyNcJbcukfi4U5MzEc\",\"_type\":\"_\",\"text\":\"После прибытия контейнера в место назначения наши специалисты проводят таможенное оформление.\"},{\"_id\":\"cf-xCmlUZEfAFIxRon9QOqKn\",\"_type\":\"_\",\"text\":\"Груз доставляется на наш склад в Одессе, а затем — к необходимому месту назначения.\"}],\"dolphincargo_delivery_steps_transport_pic\":313,\"dolphincargo_delivery_steps_road_pic\":311,\"dolphincargo_delivery_steps_image_position\":\"road\",\"dolphincargo_delivery_steps_road_pic_more\":309}} /-->\n\n<!-- wp:carbon-fields/advantages-delivery {\"data\":{\"dolphincargo_advantages_delivery_title\":\"ПРЕИМУЩЕСТВА МОРСКОЙ ДОСТАВКИ\",\"dolphincargo_advantages_delivery_list\":[{\"_id\":\"cf-ooC8q1FcxKrflPoWZZwWX\",\"_type\":\"_\",\"icon\":\"http://dolphincargo.loc/wp-content/uploads/2024/11/frame-427322787_optimized.png\",\"name\":\"Конкурентные цены.\",\"text\":\"\\u003cp\\u003e\\u003cspan style=\\u0022font-weight: 400;\\u0022\\u003eСтоимость морской доставки из Китая значительно дешевле других видов транспорта.\\u003c/span\\u003e\\u003c/p\\u003e\"},{\"_id\":\"cf-cBQD3bm26MgT8WgtzM9ly\",\"_type\":\"_\",\"icon\":\"http://dolphincargo.loc/wp-content/uploads/2024/11/frame-427322788_optimized.png\",\"name\":\"Надёжность.\",\"text\":\"\\u003cp\\u003e\\u003cspan style=\\u0022font-weight: 400;\\u0022\\u003eМорская доставка — один из самых безопасных способов перевозки грузов.\\u003c/span\\u003e\\u003c/p\\u003e\"},{\"_id\":\"cf-6jSCrEFL4iRRB99HlRD9w\",\"_type\":\"_\",\"icon\":\"http://dolphincargo.loc/wp-content/uploads/2024/11/frame-427322789_optimized.png\",\"name\":\"Потенциал.\",\"text\":\"\\u003cp\\u003e\\u003cspan style=\\u0022font-weight: 400;\\u0022\\u003eВозможность перевозки крупных объёмов груза за один раз.\\u003c/span\\u003e\\u003c/p\\u003e\"}]}} /-->\n\n<!-- wp:carbon-fields/cargo-services {\"data\":{\"dolphincargo_cargo_services_title\":\"DOLPHIN CARGO SERVICE\",\"dolphincargo_cargo_services_text\":\"\\u003cp\\u003e\\u003cspan style=\\u0022font-weight: 400;\\u0022\\u003eМы обеспечиваем высокий уровень сервиса доставки для вашего комфорта и спокойствия.\\u003c/span\\u003e\\u003c/p\\u003e\",\"dolphincargo_cargo_services_list\":[{\"_id\":\"cf-1fhglzhkHJ5LEVCLnjXuX\",\"_type\":\"_\",\"name\":\"Безопасно\",\"list\":[{\"_id\":\"cf-gh_9KLrb0EZ3bAl2AMb6J\",\"_type\":\"_\",\"text\":\"Ответственность за корректное оформление документации\"},{\"_id\":\"cf-xdD97B0nb1KwqnPvJQBuJ\",\"_type\":\"_\",\"text\":\"Полное страхование груза\"},{\"_id\":\"cf-mTDDIYwTYjpIDL4kVvQoA\",\"_type\":\"_\",\"text\":\"Проверка товаров, перепаковка и доставка\"}]},{\"_id\":\"cf-IF5YvKcpH1TEPZgNNCAPG\",\"_type\":\"_\",\"name\":\"Удобно\",\"list\":[{\"_id\":\"cf-nesvwpfPRNvPuccd2PnZ1\",\"_type\":\"_\",\"text\":\"Поддержка квалифицированного менеджера на всех этапах доставки\"},{\"_id\":\"cf-EhKZOoFafUJmAti4rwMrC\",\"_type\":\"_\",\"text\":\"Поиск и заказ товаров из Китая\"}]},{\"_id\":\"cf-0SHlJBbG1skwApJt6DhOy\",\"_type\":\"_\",\"name\":\"Надёжно\",\"list\":[{\"_id\":\"cf-DfYLHPyKH5HAPgVw_qGiP\",\"_type\":\"_\",\"text\":\"Собственные склады в Китае, ЕС и Украине для сохранности груза\"},{\"_id\":\"cf-56Me00ZuElfxpfIdZfR40\",\"_type\":\"_\",\"text\":\"Возможность консолидировать грузы на складе\"},{\"_id\":\"cf-LYjLg8E7jDMDIMHxM2_Td\",\"_type\":\"_\",\"text\":\"19 лет опыта работы в сфере доставки грузов из Китая морем\"}]}]}} /-->\n\n<!-- wp:carbon-fields/call-to-action {\"data\":{\"dolphincargo_call_to_action_title\":\"ХОТИТЕ ПОЛУЧИТЬ КОНСУЛЬТАЦИЮ?\",\"dolphincargo_call_to_action_text\":\"\\u003cp\\u003e\\u003cspan style=\\u0022font-weight: 400;\\u0022\\u003eОставьте заявку, и наши менеджеры ответят на все ваши вопросы.\\u003c/span\\u003e\\u003c/p\\u003e\",\"dolphincargo_call_to_action_image\":340}} /-->\n\n<!-- wp:carbon-fields/reviews-block {\"data\":{\"dolphincargo_block_reviews_title\":\"ОТЗЫВЫ НАШИХ КЛИЕНТОВ\"}} /-->\n\n<!-- wp:carbon-fields/faq-block {\"data\":{\"dolphincargo_block_faq_title\":\"ВОПРОСЫ И ОТВЕТЫ\",\"dolphincargo_block_faq_list\":[]}} /-->\n\n<!-- wp:carbon-fields/blog-block {\"data\":{\"dolphincargo_block_blog_title\":\"ПОЛЕЗНЫЙ КОНТЕНТ\",\"dolphincargo_block_blog_link\":[]}} /-->\n\n<!-- wp:carbon-fields/seo-block {\"data\":{\"dolphincargo_home_page_seo_title\":\"БЛОК ДЛЯ SEO-ТЕКСТА\",\"dolphincargo_home_page_seo_subtitle\":\"Заголовок\",\"dolphincargo_home_page_seo_text\":\"\\u003ch3\\u003eЗаголовок\\u003c/h3\\u003e\\u003cp\\u003e\\u003cbr /\\u003eDolphin Cargo — мы лидеры среди украинских логистических компаний, специализирующихся на доставке грузов из Китая и Европы. С 2005 г. ведем безупречную работу, регулярно масштабируя собственные возможности и улучшая сервис для наших клиентов. Dolphin Cargo — мы лидеры среди украинских логистических компаний, специализирующихся на доставке грузов из Китая и Европы. С 2005 г. ведем безупречную работу, регулярно масштабируя собственные возможности и улучшая сервис для наших клиентов.\\u003c/p\\u003e\\u003cp\\u003e \\u003c/p\\u003e\\u003cp\\u003eDolphin Cargo — мы лидеры среди украинских логистических компаний, специализирующихся на доставке грузов из Китая и Европы. С 2005 г. ведем безупречную работу, регулярно масштабируя собственные возможности и улучшая сервис для наших клиентов. Dolphin Cargo — мы лидеры среди украинских логистических компаний, специализирующихся на доставке грузов из Китая и Европы. С 2005 г. ведем безупречную работу, регулярно масштабируя собственные возможности и улучшая сервис для наших клиентов.\\u003c/p\\u003e\"}} /-->', 'Доставка грузов из Китая морем', 'Морская доставка из Китая — это экономное решение для транспортировки больших объёмов товаров. Мы обеспечиваем оптимальные маршруты и выгодные тарифы благодаря налаженным связям и опыту.', 'publish', 'closed', 'closed', '', 'dostavka-gruzov-yz-kytaya-morem', '', '', '2024-12-30 10:14:01', '2024-12-30 10:14:01', '', 0, 'http://dolphincargo.loc/?post_type=services&#038;p=194', 0, 'services', '', 0);
INSERT INTO `yudoca_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(195, 1, '2024-12-28 12:20:58', '2024-12-28 12:20:58', '<!-- wp:carbon-fields/service-main-screen {\"data\":{\"dolphincargo_service_main_screen_title\":\"АВИА ДОСТАВКА ГРУЗОВ ИЗ КИТАЯ В УКРАИНУ\",\"dolphincargo_service_main_screen_who_are_we\":\"Минимальные сроки доставки для срочных и ценных грузов\",\"dolphincargo_service_main-screen_image\":\"http://dolphincargo.loc/wp-content/uploads/2024/11/mask-group_optimized.png\"}} /-->\n\n<!-- wp:carbon-fields/our-achievement {\"data\":{\"dolphincargo_achievement_image\":348,\"dolphincargo_achievement_main\":\"6–7 тонн грузов\",\"dolphincargo_achievement_description\":\"Еженедельно отправляем самолетом\",\"dolphincargo_achievement_list\":[{\"_id\":\"cf-tlX6xql1Tt0I04FON788S\",\"_type\":\"_\",\"name\":\"Оперативная доставка грузов\",\"description\":\"\\u003cp\\u003e\\u003cspan style=\\u0022font-weight: 400;\\u0022\\u003eАвиаперевозки — самый быстрый способ доставки грузов. Сроки доставки при заказе услуги составляют от 14 дней.\\u003c/span\\u003e\\u003c/p\\u003e\"},{\"_id\":\"cf-Xu8xxqubYCE8Qjn_vEhPa\",\"_type\":\"_\",\"name\":\"Комплексные решения для вашего бизнеса\",\"description\":\"\\u003cp\\u003e\\u003cspan style=\\u0022font-weight: 400;\\u0022\\u003eМы обеспечиваем надлежащий приём груза на складе, инспекцию и страхование, таможенно-брокерские услуги и контроль безопасности на каждом этапе перевозки.\\u003c/span\\u003e\\u003c/p\\u003e\"}]}} /-->\n\n<!-- wp:carbon-fields/warrantyservices {\"data\":{\"dolphincargo_warranty_title\":\"НАШИ ГАРАНТИИ\",\"dolphincargo_warranty_list\":[{\"_id\":\"cf-HKd_kvi2KuNz3BIGZFj0w\",\"_type\":\"_\",\"name\":\"Безопасность грузов\",\"image\":357},{\"_id\":\"cf-tfXFKYAH_TcU3ynI2Dbzr\",\"_type\":\"_\",\"name\":\"Доставка в обозначенные сроки\",\"image\":351},{\"_id\":\"cf-HFmA7zAF5vAtW768nyhVg\",\"_type\":\"_\",\"name\":\"Страхование грузов\",\"image\":353},{\"_id\":\"cf-60T8XlbJbjDioA4pmoD2s\",\"_type\":\"_\",\"name\":\"Полная конфиденциальность\",\"image\":355}],\"dolphincargo_warranty_logic\":\"no\"}} /-->\n\n<!-- wp:carbon-fields/calculate-shipping {\"data\":{\"dolphincargo_calculate_shipping_title\":\"ХОТИТЕ РАССЧИТАТЬ СТОИМОСТЬ ДОСТАВКИ?\",\"dolphincargo_calculate_shipping_text\":\"\\u003cp\\u003e\\u003cspan style=\\u0022font-weight: 400;\\u0022\\u003eНаши менеджеры подберут лучшие индивидуальные решения и рассчитают стоимость услуг.\\u003c/span\\u003e\\u003cspan style=\\u0022font-weight: 400;\\u0022\\u003e\\u003cbr /\\u003e\\u003c/span\\u003e\\u003c/p\\u003e\",\"dolphincargo_calculate_shipping_image\":306}} /-->\n\n<!-- wp:carbon-fields/delivery-steps {\"data\":{\"dolphincargo_delivery_steps_title\":\"КАК РАБОТАЕТ НАША ДОСТАВКА?\",\"dolphincargo_delivery_steps_list\":[{\"_id\":\"cf-mYeSIm79J0rhRgF9WEmwm\",\"_type\":\"_\",\"text\":\"Вы оставляете заявку и выбираете условия перевозки вместе с персональным менеджером.\"},{\"_id\":\"cf-uioxFkpcrVAtUdJMsBUTJ\",\"_type\":\"_\",\"text\":\"Поставщик отправляет груз на наш склад. После получения специалисты проверяют упаковку и готовят груз к авиаперевозке.\"},{\"_id\":\"cf-VpeKqEkyxtWdKyJi7oJNS\",\"_type\":\"_\",\"text\":\"Мы оформляем все необходимые таможенные документы, включая сертификаты и счета.\"},{\"_id\":\"cf-W_bCr0vde6daCCc_O7THC\",\"_type\":\"_\",\"text\":\"Груз доставляется в аэропорт, где специалисты контролируют погрузку на самолёт.\"},{\"_id\":\"cf-lMkbK8BYJlnb8L1i6Q59l\",\"_type\":\"_\",\"text\":\"В процессе транспортировки мы остаёмся на связи, отслеживаем груз и контролируем график доставки.\"},{\"_id\":\"cf-YwYcOJ88wfUFeDqTjv5aY\",\"_type\":\"_\",\"text\":\"После прибытия груза в место назначения мы проводим таможенное оформление.\"},{\"_id\":\"cf-EbdgqrFOsT4geBHDpWjpO\",\"_type\":\"_\",\"text\":\"Груз доставляется на наш склад в Одессе, а затем отправляется в ваш город.\"}],\"dolphincargo_delivery_steps_transport_pic\":363,\"dolphincargo_delivery_steps_road_pic\":361,\"dolphincargo_delivery_steps_image_position\":\"\",\"dolphincargo_delivery_steps_road_pic_more\":\"\"}} /-->\n\n<