\":\"Страхование груза\",\"image\":353},{\"_id\":\"cf-Ve_PyarBthgyXcB_QAQwt\",\"_type\":\"_\",\"name\":\"Полная конфиденциальность\",\"image\":355}],\"dolphincargo_warranty_logic\":\"no\"}} /-->\n\n<!-- wp:carbon-fields/calculate-shipping {\"data\":{\"dolphincargo_calculate_shipping_title\":\"ХОТИТЕ РАССЧИТАТЬ СТОИМОСТЬ ДОСТАВКИ?\",\"dolphincargo_calculate_shipping_text\":\"\\u003cp\\u003e\\u003cspan style=\\u0022font-weight: 400;\\u0022\\u003eНаши менеджеры подберут индивидуальные решения и рассчитают стоимость услуг.\\u003c/span\\u003e\\u003cspan style=\\u0022font-weight: 400;\\u0022\\u003e\\u003cbr /\\u003e\\u003c/span\\u003e\\u003c/p\\u003e\",\"dolphincargo_calculate_shipping_image\":306}} /-->\n\n<!-- wp:carbon-fields/delivery-steps {\"data\":{\"dolphincargo_delivery_steps_title\":\"КАК РАБОТАЕТ НАША ДОСТАВКА?\",\"dolphincargo_delivery_steps_list\":[{\"_id\":\"cf-Kha6X4U6QdgL72Zb2O4Nn\",\"_type\":\"_\",\"text\":\"Вы оставляете заявку и выбираете условия перевозки с персональным менеджером.\"},{\"_id\":\"cf-XDsPMVaeA3hwMxTkTdZ5X\",\"_type\":\"_\",\"text\":\"Поставщик отправляет груз на наш склад. После получения товара, наши специалисты проверяют упаковку и готовят груз к отправке поездом.\"},{\"_id\":\"cf-KPntysrOEI_P3003C3png\",\"_type\":\"_\",\"text\":\"Мы оформляем все необходимые таможенные документы для экспорта груза из Китая.\"},{\"_id\":\"cf-7ysYLcXcrr_ltEtlOSF0K\",\"_type\":\"_\",\"text\":\"Ваш груз загружается в сборный контейнер на железнодорожном терминале и отправляется поездом по установленному маршруту к месту назначения.\"},{\"_id\":\"cf-pwq5hohk7kv9oPWBbfbCS\",\"_type\":\"_\",\"text\":\"В процессе перевозки мы остаёмся на связи с операторами, отслеживаем груз и контролируем график доставки.\"},{\"_id\":\"cf-diq98Q0OkP8XWyjTnz3PQ\",\"_type\":\"_\",\"text\":\"После прибытия поезда в пункт назначения специалисты проводят таможенное оформление груза.\"},{\"_id\":\"cf-K5QPSYPHmHhLNOZpD967Y\",\"_type\":\"_\",\"text\":\"Груз доставляется на наш склад 