(198, 1, '2024-12-28 12:23:41', '2024-12-28 12:23:41', '', 'Поиск и выкуп товаров в Китае', 'Мы сотрудничаем с большим количеством надёжных производителей, что позволяет найти необходимые товары. Благодаря нашему опыту вы сможете избежать рисков, связанных с заказом продукции из-за границы.\n', 'publish', 'closed', 'closed', '', 'poysk-y-vykup-tovarov-v-kytae', '', '', '2024-12-29 14:19:53', '2024-12-29 14:19:53', '', 0, 'http://dolphincargo.loc/?post_type=services&#038;p=198', 0, 'services', '', 0),
(199, 1, '2024-12-28 12:24:45', '2024-12-28 12:24:45', '', 'Доставка грузов под ключ', 'Доставка грузов с контролем профессионалов на каждом этапе: от поиска товаров до получения необходимого груза. Мы берём на себя всю работу, чтобы ваш груз прибыл точно в срок и без лишних хлопот.\n', 'publish', 'closed', 'closed', '', 'dostavka-gruzov-pod-klyuch', '', '', '2024-12-28 12:24:45', '2024-12-28 12:24:45', '', 0, 'http://dolphincargo.loc/?post_type=services&#038;p=199', 0, 'services', '', 0),
(200, 1, '2024-12-28 12:26:12', '2024-12-28 12:26:12', '<!-- wp:carbon-fields/main-screen {\"data\":{\"dolphincargo_home_page_main_screen_title\":\"DOLPHIN Cargo Service\",\"dolphincargo_home_page_main-screen_who_are_we\":\"Доставка грузов из Китая и Европы Надежно, вовремя и безопасно\",\"dolphincargo_home_page_main-screen_image\":\"http://dolphincargo.loc/wp-content/uploads/2024/12/home-main-bg_optimized.png\",\"dolphincargo_home_page_our_numbers_list\":[{\"_id\":\"cf-9BR4MNTKAVprUsSAl2t_D\",\"_type\":\"_\",\"number\":\"19 \",\"number_more\":\" лет \",\"description\":\"опыта и экспертности\"},{\"_id\":\"cf-I0nnP_MEKHD182uFLv2cM\",\"_type\":\"_\",\"number\":\"3400\",\"number_more\":\"+ \",\"description\":\"постоянных клиентов и партнёров\"},{\"_id\":\"cf-qERFh7xG5bQIqbhqwaiFC\",\"_type\":\"_\",\"number\":\"16700\",\"number_more\":\"+ \",\"description\":\"заказов за 2024 год\"}]}} /-->\n\n<!-- wp:carbon-fields/what-you-get {\"data\":{\"dolphincargo_home_page_what_you_get_list\":[{\"_id\":\"cf-_xXPaFKjlcxCkSpZ9Gbrt\",\"_type\":\"_\",\"text\":\"Без посредников и переплат\"},{\"_id\":\"cf-SFsd8TqVmdhFBNGs7axDl\",\"_type\":\"_\",\"text\":\"Собственные склады в ключевых транспортных узлах\"},{\"_id\":\"cf-eQrCtOkqFMScH2u3VpGNb\",\"_type\":\"_\",\"text\":\"Страхование груза и гарантия безопасности\"},{\"_id\":\"cf-55hRdUCGQRVOsROJUyQBd\",\"_type\":\"_\",\"text\":\"Полная конфиденциальность и вся необходимая документация\"}],\"dolphincargo_home_page_what_you_get_list_image\":190}} /-->\n\n<!-- wp:carbon-fields/services-list {\"data\":{\"dolphincargo_our_services_title\":\"НАШИ УСЛУГИ\",\"dolphincargo_our_services_list\":[{\"id\":195,\"type\":\"post\",\"subtype\":\"services\"},{\"id\":194,\"type\":\"post\",\"subtype\":\"services\"},{\"id\":199,\"type\":\"post\",\"subtype\":\"services\"},{\"id\":196,\"type\":\"post\",\"subtype\":\"services\"},{\"id\":198,\"type\":\"post\",\"subtype\":\"services\"},{\"id\":197,\"type\":\"post\",\"subtype\":\"services\"}],\"dolphincargo_our_services_run_text\":\"Services of the transportation \\u0026 logistics company DOLPHIN CARGO\"}} /-->\n\n<!-- wp:carbon-fields/airplane-call-to-action {\"data\":{\"dolphincargo_home_call_to_title\":\"НЕ МОЖЕТЕ ОПРЕДЕЛИТЬСЯ С ОПТИМАЛЬНЫМ СПОСОБОМ ДОСТАВКИ?\",\"dolphincargo_home_call_to_text\":\"\\u003cp\\u003e\\u003cspan style=\\u0022font-weight: 400;\\u0022\\u003eНаши менеджеры подберут лучшие индивидуальные решения под запросы вашего бизнеса.\\u003c/span\\u003e\\u003c/p\\u003e\",\"dolphincargo_home_call_to_image\":208}} /-->\n\n<!-- wp:carbon-fields/about-us {\"data\":{\"dolphincargo_block_about_us_title\":\"ПРОВЕРЕННЫЕ ВРЕМЕНЕМ — ОБУЧЕННЫЕ ОПЫТОМ\",\"dolphincargo_block_about_us_text\":\"\\u003cp\\u003e\\u003cb\\u003eDolphin Cargo\\u003c/b\\u003e\\u003cspan style=\\u0022font-weight: 400;\\u0022\\u003e — мы лидеры среди украинских логистических компаний, специализирующихся на доставке грузов из Китая и Европы. С 2005 года мы ведём безупречную работу, регулярно расширяем свои возможности и улучшаем сервис для наших клиентов.\\u003c/span\\u003e\\u003c/p\\u003e\\u003cp\\u003e\\u003cspan style=\\u0022font-weight: 400;\\u0022\\u003eМы берём на себя решение всех вопросов логистики, организации и документооборота транспортировки грузов.\\u003c/span\\u003e\\u003cspan style=\\u0022font-weight: 400;\\u0022\\u003e\\u003cbr /\\u003e\\u003c/span\\u003e\\u003c/p\\u003e\",\"dolphincargo_block_about_us_gallery\":[{\"_id\":\"cf-8_wBqCtaaqpdG96dDt7IO\",\"_type\":\"_\",\"image\":211},{\"_id\":\"cf-WfpV_TL6vBs34n3oBnfEY\",\"_type\":\"_\",\"image\":213},{\"_id\":\"cf-wwZ0iBXJrRmGydJHw6D8Y\",\"_type\":\"_\",\"image\":212}],\"dolphincargo_block_about_us_link\":[]}} /-->\n\n<!-- wp:carbon-fields/advantages {\"data\":{\"dolphincargo_block_advantages_title\":\"ВАШ НАДЁЖНЫЙ ПАРТНЁР В ГРУЗОПЕРЕВОЗКАХ\",\"dolphincargo_block_advantages_list\":[{\"_id\":\"cf-yMJxqUOt8aiCMrr2h1b6G\",\"_type\":\"_\",\"name\":\"У нас есть собственные склады в ключевых транспортных узлах: Китай, ЕС, Украина.\",\"description\":\"\\u003cp\\u003e\\u003cspan style=\\u0022font-weight: 400;\\u0022\\u003eЭто позволяет нам обеспечивать надёжную и оперативную доставку грузов из Китая и Европы, сокращать время транзита, ваши расходы и обеспечивать высокий уровень сервиса.\\u003c/span\\u003e\\u003c/p\\u003e\"},{\"_id\":\"cf-QMOGjVxHbrBFmSfcrLAfV\",\"_type\":\"_\",\"name\":\"Работаем на результат и понимаем потребности современных бизнесов\",\"description\":\"\\u003cp\\u003e\\u003cspan style=\\u0022font-weight: 400;\\u0022\\u003eОбеспечиваем полный цикл услуг по грузоперевозкам, находим гибкие решения для достижения поставленных задач, используем мультимодальные перевозки.\\u003c/span\\u003e\\u003c/p\\u003e\"},{\"_id\":\"cf-qTR12D2Gi4ks1xU3mIjLh\",\"_type\":\"_\",\"name\":\"Гарантируем прозрачность и экономное планирование вашего бюджета\",\"description\":\"\\u003cp\\u003e\\u003cspan style=\\u0022font-weight: 400;\\u0022\\u003eПредоставляем индивидуальный расчёт стоимости доставки и находим наиболее эффективные решения для перевозки ваших грузов.\\u003c/span\\u003e\\u003c/p\\u003e\"},{\"_id\":\"cf-xYgNfm3rg16hw4ZB2RzJq\",\"_type\":\"_\",\"name\":\"За вами закрепляется персональный менеджер\",\"description\":\"\\u003cp\\u003e\\u003cspan style=\\u0022font-weight: 400;\\u0022\\u003eС момента первой заявки и до получения груза наши менеджеры оказывают профессиональное сопровождение и квалифицированную поддержку на каждом этапе.\\u003c/span\\u003e\\u003c/p\\u003e\"}],\"dolphincargo_block_advantages_top_image\":216,\"dolphincargo_block_advantages_bottom_image\":217}} /-->\n\n<!-- wp:carbon-fields/reviews-block {\"data\":{\"dolphincargo_block_reviews_title\":\"ОТЗЫВЫ НАШИХ КЛИЕНТОВ\"}} /-->\n\n<!-- wp:carbon-fields/faq-block {\"data\":{\"dolphincargo_block_faq_title\":\"ВОПРОСЫ И ОТВЕТЫ\",\"dolphincargo_block_faq_list\":[{\"_id\":\"cf-vSwTlRiwUoBmdIrk0TIcX\",\"_type\":\"_\",\"question\":\"Можете ли вы помочь с подбором поставщиков в Китае?\",\"answer\":\"\\u003cp\\u003eDolphin Cargo — мы лидеры среди украинских логистических компаний, специализирующихся на доставке грузов из Китая и Европы. С 2005 г. ведем безупречную работу, регулярно масштабируя собственные возможности и улучшая сервис для наших клиентов. Dolphin Cargo — мы лидеры среди украинских логистических компаний, специализирующихся на доставке грузов из Китая и Европы. С 2005 г. ведем безупречную работу, регулярно масштабируя собственные возможности и улучшая сервис для наших клиентов.\\u003c/p\\u003e\"},{\"_id\":\"cf-3tGyB__qzBJG3MY_Fgvsc\",\"_type\":\"_\",\"question\":\"Можете ли вы помочь с подбором поставщиков в Китае?\",\"answer\":\"\\u003cp\\u003eDolphin Cargo — мы лидеры среди украинских логистических компаний, специализирующихся на доставке грузов из Китая и Европы. С 2005 г. ведем безупречную работу, регулярно масштабируя собственные возможности и улучшая сервис для наших клиентов. Dolphin Cargo — мы лидеры среди украинских логистических компаний, специализирующихся на доставке грузов из Китая и Европы. С 2005 г. ведем безупречную работу, регулярно масштабируя собственные возможности и улучшая сервис для наших клиентов.\\u003c/p\\u003e\"}]}} /-->\n\n<!-- wp:carbon-fields/blog-block {\"data\":{\"dolphincargo_block_blog_title\":\"ПОЛЕЗНЫЙ КОНТЕНТ\",\"dolphincargo_block_blog_link\":[]}} /-->', 'Главная', '', 'publish', 'closed', 'closed', '', 'glavnaya', '', '', '2024-12-28 12:42:11', '2024-12-28 12:42:11', '', 0, 'http://dolphincargo.loc/?page_id=200', 0, 'page', '', 0),
