(428, 1, '2025-01-07 18:13:30', '2025-01-07 18:13:30', '<!-- wp:carbon-fields/service-main-screen {\"data\":{\"dolphincargo_service_main_screen_title\":\"ЯК МИ ПРАЦЮЄМО\",\"dolphincargo_service_main_screen_who_are_we\":\"Повний супровід та максимальна увага до ваших потреб\",\"dolphincargo_service_main-screen_image\":\"http://dolphincargo.loc/wp-content/uploads/2025/01/how-we-work-main-pic.png\"}} /-->\n\n<!-- wp:carbon-fields/slogan {\"data\":{\"dolphincargo_block_slogan_title\":\"Наш підхід до співпраці – прозорість, ефективність та турбота про ваш вантаж. \",\"dolphincargo_block_slogan_text\":\"\\u003cp\\u003eМи забезпечуємо кожен етап доставки, починаючи з моменту надходження вантажу на склад та завершуючи його доставкою «до дверей».\\u003c/p\\u003e\",\"dolphincargo_block_slogan_marquee\":\"ПРАЦЮЄМО ДЛЯ ВАШОГО КОМФОРТУ\"}} /-->\n\n<!-- wp:carbon-fields/cooperation-stages {\"data\":{\"dolphincargo_cooperation_stage_title\":\"ОСНОВНІ ЕТАПИ СПІВПРАЦІ З НАМИ\",\"dolphincargo_cooperation_stage_list\":[{\"_id\":\"cf-OYvNbVRhASgHDjEBfZjC8\",\"_type\":\"_\",\"icon\":\"http://dolphincargo.loc/wp-content/uploads/2025/01/frame-427322789_optimized.png\",\"name\":\"Запит та консультація\",\"so_name\":\"\",\"steps_title\":\"\",\"inner_list\":[{\"_id\":\"cf-xGSk5dHK49u0OX7PYkChR\",\"_type\":\"_\",\"text\":\"Ви залишаєте заявку на сайті або телефонуєте нам.\"},{\"_id\":\"cf-wxtaY2HGcnFaCKKdF8N_x\",\"_type\":\"_\",\"text\":\"Ми аналізуємо ваш запит і формуємо оптимальну пропозицію.\"},{\"_id\":\"cf-F0ZXSUdLjG277MVwVy5b1\",\"_type\":\"_\",\"text\":\"Ви отримуєте персональну консультацію та розрахунок вартості послуг.\"}]},{\"_id\":\"cf-opfP83sQzQFVwyfpTPOae\",\"_type\":\"_\",\"icon\":\"http://dolphincargo.loc/wp-content/uploads/2025/01/frame-427322790_optimized.png\",\"name\":\"Пошук і викуп товару (опціонально)\",\"so_name\":\"\",\"steps_title\":\"\",\"inner_list\":[{\"_id\":\"cf-k7GAferbmwQtQ0A2EJs3b\",\"_type\":\"_\",\"text\":\"Наші експерти знаходять в Китаї необхідні товари для вас та обирають постачальників з найвигіднішими умовами.\"},{\"_id\":\"cf-qH6_Bahh6faR37ZWx3VYM\",\"_type\":\"_\",\"text\":\"Ми беремо на себе весь процес викупу, включно з оплатою через місцеві платіжні системи.\"}]},{\"_id\":\"cf-p9TfEfmz_bnjbxdig6Od8\",\"_type\":\"_\",\"icon\":\"http://dolphincargo.loc/wp-content/uploads/2025/01/frame-427322791_optimized.png\",\"name\":\"Забір вантажу та підготовка до відправки\",\"so_name\":\"\",\"steps_title\":\"\",\"inner_list\":[{\"_id\":\"cf-_FFfLI0gfvgZXNBTLje5u\",\"_type\":\"_\",\"text\":\"Отримуємо вантаж на наших складах в Китаї чи Європі.\"},{\"_id\":\"cf-S6k52o0l_lkGpsE6MN4fb\",\"_type\":\"_\",\"text\":\"Проводимо перевірку, пакування та підготовку товару до відправлення.\"}]},{\"_id\":\"cf-B1W8yLk9sPiY2AhVCSP4n\",\"_type\":\"_\",\"icon\":\"http://dolphincargo.loc/wp-content/uploads/2025/01/frame-427322792_optimized.png\",\"name\":\"Митне оформлення\",\"so_name\":\"\",\"steps_title\":\"\",\"inner_list\":[{\"_id\":\"cf-7Cpy1FmjNH87GoW3zNjuv\",\"_type\":\"_\",\"text\":\"Перевірка та підготовка всіх документів для транспортування вантажів.\"},{\"_id\":\"cf-7YOreNPFuaO47wc_R5PSv\",\"_type\":\"_\",\"text\":\"Експерти Dolphin Cargo роблять все для швидкого та безпроблемного проходження митниці.\"}]},{\"_id\":\"cf-5KkMQvQIbdsoZBv4b7Ru6\",\"_type\":\"_\",\"icon\":\"http://dolphincargo.loc/wp-content/uploads/2025/01/frame-427322793_optimized.png\",\"name\":\"Транспортування\",\"so_name\":\"Під час перевезення відстежуємо вантаж та інформуємо вас про його статус\",\"steps_title\":\"Ми пропонуємо різні варіанти доставки:\",\"inner_list\":[{\"_id\":\"cf-HpG5r_cp7JdcsRl517dfo\",\"_type\":\"_\",\"text\":\"Морські перевезення — економічне рішення для великих партій.\"},{\"_id\":\"cf-zQ05hzVtrFEw4x6UAmLgF\",\"_type\":\"_\",\"text\":\"Авіа — для швидкої доставки термінових вантажів.\"},{\"_id\":\"cf-HSTxLfxzkr84HnRPPiGYm\",\"_type\":\"_\",\"text\":\"Залізниця —  баланс між швидкістю та вартістю.\"}]},{\"_id\":\"cf-HeQl2P37KAMd9EQA5hk1S\",\"_type\":\"_\",\"icon\":\"http://dolphincargo.loc/wp-content/uploads/2025/01/frame-427322794_optimized.png\",\"name\":\"Доставка в Україну\",\"so_name\":\"\",\"steps_title\":\"\",\"inner_list\":[{\"_id\":\"cf-bVKS4zRFti71a1uQC7SYZ\",\"_type\":\"_\",\"text\":\"По прибутті вантажу до України ми проводимо імпортне митне оформлення.\"},{\"_id\":\"cf-sl52mpWpR40VcoGtdZjQ4\",\"_type\":\"_\",\"text\":\"Організовуємо подальшу доставку до місця призначення.\"}]}]}} /-->', 'Як ми працюємо', '', 'inherit', 'closed', 'closed', '', '410-revision-v1', '', '', '2025-01-07 18:13:30', '2025-01-07 18:13:30', '', 410, 'http://dolphincargo.loc/?p=428', 0, 'revision', '', 0),
